71	func runSessionsFix(cmd *cobra.Command, force bool) error {
72		var finalErr error
73	
74		// Check 1: Disconnected metadata branches
75		metadataErr := checkDisconnectedMetadata(cmd, force)
76		if metadataErr != nil {
77			fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
78			finalErr = NewSilentError(fmt.Errorf("metadata check failed: %w", metadataErr))
79		}
80		fmt.Fprintln(cmd.OutOrStdout())
81	
82		// Check 2: Stuck sessions
83		ctx := cmd.Context()
84		// Load all session states
85		states, err := strategy.ListSessionStates(ctx)
86		if err != nil {
87			return fmt.Errorf("failed to list session states: %w", err)
88		}
89	
90		if len(states) == 0 {
91			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
92			if finalErr != nil {
93				return finalErr
94			}
95			return nil
96		}
97	
98		// Open repository to check shadow branches (uses worktree-aware helper)
99		repo, err := openRepository(ctx)
100		if err != nil {
101			return fmt.Errorf("failed to open repository: %w", err)
102		}
103	
104		// Identify stuck sessions
105		now := time.Now()
106		var stuck []stuckSession
107	
108		for _, state := range states {
109			ss := classifySession(state, repo, now)
110			if ss != nil {
111				stuck = append(stuck, *ss)
112			}
113		}
114	
115		if len(stuck) == 0 {
116			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
117			if finalErr != nil {
118				return finalErr
119			}
120			return nil
121		}
122	
123		// Get the current strategy for condense operations
124		strat := GetStrategy(ctx)
125	
126		fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
127	
128		for _, ss := range stuck {
129			displayStuckSession(cmd, ss)
130	
131			if force {
132				if ss.HasShadowBranch && ss.CheckpointCount > 0 {
133					if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
134						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
135					} else {
136						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
137					}
138				} else {
139					// Discard if we can't condense
140					if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
141						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
142					} else {
143						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
144					}
145				}
146				continue
147			}
148	
149			// Interactive: prompt for action
150			action, err := promptSessionAction(ss)
151			if err != nil {
152				if errors.Is(err, huh.ErrUserAborted) {
153					return nil
154				}
155				return fmt.Errorf("failed to get action: %w", err)
156			}
157	
158			switch action {
159			case "condense":
160				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
161					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
162				} else {
163					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
164				}
165			case "discard":
166				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
167					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
168				} else {
169					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
170				}
171			case "skip":
172				fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
173			}
174		}
175	
176		if finalErr != nil {
177			return finalErr
178		}
179	
180		return nil
181	}
