79	// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
80	// It first checks the writer itself, then falls back to Stdout/Stderr.
81	func getTerminalWidth(w io.Writer) int {
82		// Try the output writer first
83		if f, ok := w.(*os.File); ok {
84			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
85				return min(width, 80)
86			}
87		}
88	
89		// Fall back to Stdout, then Stderr
90		for _, f := range []*os.File{os.Stdout, os.Stderr} {
91			if f == nil {
92				continue
93			}
94			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
95				return min(width, 80)
96			}
97		}
98	
99		return 60
100	}
