102	// formatTokenCount formats a token count for display.
103	// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
104	func formatTokenCount(n int) string {
105		if n < 1000 {
106			return strconv.Itoa(n)
107		}
108		f := float64(n) / 1000.0
109		s := fmt.Sprintf("%.1f", f)
110		// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
111		s = strings.TrimSuffix(s, ".0")
112		return s + "k"
113	}
