131	// sectionRule renders a section header like: ── Active Sessions ────────────
132	func (s statusStyles) sectionRule(label string, width int) string {
133		prefix := "── "
134		content := label + " "
135		usedWidth := len([]rune(prefix)) + len([]rune(content))
136		trailing := width - usedWidth
137		if trailing < 1 {
138			trailing = 1
139		}
140	
141		var b strings.Builder
142		b.WriteString(s.render(s.dim, "── "))
143		b.WriteString(s.render(s.dim, label))
144		b.WriteString(" ")
145		b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
146		return b.String()
147	}
