// isStaleSession returns true if the session is in ACTIVE phase but has not
// had any interaction for longer than the staleness threshold (defined in
// doctor.go). This matches the same criteria doctor uses to flag stuck sessions.
func isStaleSession(st *session.State) bool {
	if !st.Phase.IsActive() {
		return false
	}
	if st.LastInteractionTime == nil {
		return true
	}
	return time.Since(*st.LastInteractionTime) > stalenessThreshold
}
